  const page = nav.find(n => (n === 'Inventory' ? 'inventory' : n.toLowerCase()) === route) || (route === 'join' ? 'Join workspace' : 'Overview');
  const showModal = (type: string, item?: Row) => setModal({ type, item });
  const filter = (rows: Row[], fields: string[]) => rows.filter(x => fields.some(k => String(x[k] || '').toLowerCase().includes(search.toLowerCase())));
